      "5歳男児。体重19 kg。歯の痛みのため、母親が自分用として購入していた市販薬の痛み止め（1錠当たり、アスピリン300 mg、無水カフェイン25 mgを含む）を2時間ごとに2錠、計5回服用させたところ、嘔吐、腹痛が出現したので受診した。受診時のサリチル酸の血中濃度は36.5 mg/dLであった。受診後は、活性炭や下剤の投与と強制利尿を行うとともに（[[A|]]）の投与を行い、翌日には完治退院した。男児の肝機能及び腎機能は正常であった。\n\n（A）に該当する最も適切なのはどれか。1つ選べ。",

    choices: [
    "アセチルシステイン内用液",
    "イダルシズマブ（遺伝子組換え）静注液",
    "炭酸水素ナトリウム注射液",
    "メチルチオニニウム塩化物水和物（メチレンブルー）静注",
    "亜硝酸アミル"
    ],

    answer: 2,


    explanation:
      "本例はアスピリンを短時間に多量服用しており、サリチル酸中毒が考えられます。サリチル酸は弱酸性薬物であり、炭酸水素ナトリウムにより尿をアルカリ化するとイオン化が進み、腎排泄が促進されます。また、代謝性アシドーシスの補正にも有用です。したがって（A）は炭酸水素ナトリウム注射液が適切です。アセチルシステインはアセトアミノフェン中毒、イダルシズマブはダビガトランの中和、メチレンブルーはメトヘモグロビン血症、亜硝酸アミルはシアン中毒などで用いられるため、本問では該当しません。"
