    caseContext:
      "22歳男性。身長175 cm、体重60 kg。花粉症の症状がひどくなったので、家族が使用していた一般用医薬品の小青竜湯エキス顆粒の服用を考えたが、陸上競技の国体選手であったため、かかりつけ薬剤師に相談した。薬剤師は、小青竜湯エキス顆粒にはアンチ・ドーピング規程における禁止物質が含まれるため、服用しないよう指示した上で、近隣の医療機関への受診を勧奨した。その結果、次の薬剤が処方されたので、薬剤師が処方監査を行った。\n\n（処方）\nフェキソフェナジン塩酸塩錠 60 mg　1回1錠（1日2錠）\n1日2回　朝夕食後　14日分\nベタメタゾン錠 0.5 mg　鼻水のひどいとき　1回1錠　10回分（10錠）\nフルチカゾンフランカルボン酸エステル点鼻液 27.5 μg　56噴霧用　1本\n1回2噴霧　両鼻腔　1日1回　点鼻\nフルオロメトロン点眼液 0.1%（5 mL/本）　1本\n1回1滴　1日4回　両眼点眼\nエピナスチン塩酸塩点眼液 0.05%（5 mL/本）　1本\n1回1滴　1日4回　両眼点眼",
