      "68歳男性。2週間前から労作時呼吸困難が出現し、増悪傾向のため医療機関を受診した。心房細動、左室駆出率（LVEF）の低下した心不全と診断され、酸素投与も必要なため入院加療となった。その後、軽快し、以下の処方で治療されている。\n\n（処方）\nアピキサバン錠 2.5 mg　1回1錠（1日2錠）\n1日2回　朝夕食後　7日分\nビソプロロールテープ 4 mg　1回1枚（1日1枚）\n1日1回　朝　7日分\n胸部、上腕部又は背部に貼付（全7枚）\n\n身体所見・検査値\n心エコー心嚢液なし、右心不全所見なし、LVEF 45%、CCr 23 mL/min、ヘマトクリット値 32.9%、血清アルブミン 3.3 g/dL、血清クレアチニン 2.25 mg/dL、Na 139 mq/L、K 4.4 mq/L、BNP 452.7 pg/mL、心拍数 120回/分、血圧 150/90 mmHg\n\n上記の検査値を確認し、心拍数の調節が不十分なため、心拍数の調節を目的として薬剤Aが追加された。",
    field: "実務",

    question:
      "68歳男性。2週間前から労作時呼吸困難が出現し、増悪傾向のため医療機関を受診した。心房細動、左室駆出率（LVEF）の低下した心不全と診断され、酸素投与も必要なため入院加療となった。その後、軽快し、以下の処方で治療されている。\n\n（処方）\nアピキサバン錠2.5 mg 1回1錠（1日2錠）\n1日2回 朝夕食後 7日分\nビソプロロールテープ4 mg 1回1枚（1日1枚）\n1日1回 朝 7日分\n胸部、上腕部又は背部に貼付（全7枚）\n\n身体所見・検査値\n心エコー心嚢液なし、右心不全所見なし、LVEF 45%、CCr 23 mL/min、ヘマトクリット値32.9%、血清アルブミン3.3 g/dL、血清クレアチニン2.25 mg/dL、Na 139 mEq/L、K 4.4 mEq/L、BNP 452.7 pg/mL、心拍数120回/分、血圧150/90 mmHg\n\n上記の検査値を確認し、心拍数の調節が不十分なため、心拍数の調節を目的として薬剤Aが追加された。\n\n薬剤Aとして最も適切なのはどれか。1つ選べ。",

