      "60歳男性。喫煙歴なし。極端な運動不足である。特定健康診査の案内が来ていたので、健診を受けることになった。後日、実施機関から健診結果及びこれに応じた生活習慣の改善に関する情報が届いたので、自宅近くの薬局を訪れ、薬剤師に相談した。健診結果は身長165 cm、体重81.7 kg、BMI 30、腹囲100 cm、収縮期血圧155 mmHg、拡張期血圧95 mmHg、中性脂肪220 mg/dL、HDL-C 35 mg/dL、空腹時血糖値90 mg/dL、HbA1c 5.2%（NGSP値）であった。",
    field: "実務",

    question:
      "60歳男性。喫煙歴なし。極端な運動不足である。特定健康診査の案内が来ていたので、健診を受けることになった。後日、実施機関から健診結果及びこれに応じた生活習慣の改善に関する情報が届いたので、自宅近くの薬局を訪れ、薬剤師に相談した。健診結果は身長165 cm、体重81.7 kg、BMI 30、腹囲100 cm、収縮期血圧155 mmHg、拡張期血圧95 mmHg、中性脂肪220 mg/dL、HDL-C 35 mg/dL、空腹時血糖値90 mg/dL、HbA1c 5.2％（NGSP 値）であった。\n\nこの特定健康診査の結果から、この男性は特定保健指導の対象者となった。その原因となった検査項目として誤っているのはどれか。1つ選べ。",

