    field: "実務",

    question:
      "30歳女性。少し前から物が二重に見えることがあり、最近は階段を上るときに下肢のだるさを感じるようになった。また、夜は歯磨き程度でも腕が疲れるようになったため受診した。早期の重症筋無力症と診断され、以下の薬剤が処方された。\n\n（処方1）\nピリドスチグミン臭化物錠60mg 1回1錠（1日3錠）\n1日3回 朝昼夕食後 7日分\n\n（処方2）\nプレドニゾロン錠5mg 1回2錠（1日2錠）\n1日1回 朝食後 7日分\n\n（処方3）\nタクロリムスカプセル1mg 1回3カプセル（1日3カプセル）\n1日1回 夕食後 7日分\n\nこの患者の処方に関する記述のうち適切なのはどれか。2つ選べ。",

