      "75歳男性。大腸がんステージIVに対して、mFOLFOX6療法により治療中である。原発巣の痛みに対し、処方1の薬剤が投与されていたが痛みのコントロールが不十分であった。そのため、処方2を追加（1週間ごとに増量）したところ、NRS（Numerical Rating Scale）は6/10から徐々に低下し持続痛はほとんどなくなり、開始16日目にはNRSは2/10となった。しかし、開始18日目に下痢、発汗、発熱、見当識障害が出現し、開始25日目に不眠、焦燥感、体重減少を訴え、処方薬による副作用が疑われ、血液検査を行った。\n\n（処方1）\nアセトアミノフェン錠500 mg　1回2錠（1日8錠）\n1日4回　朝昼夕食後・就寝前　28日分\nアミトリプチリン塩酸塩錠25 mg　1回1錠（1日1錠）\n1日1回　就寝前　28日分\n\n（処方2）\n（1〜7日目）トラマドール塩酸塩口腔内崩壊錠25 mg\n1回1錠（1日4錠）\n1日4回　朝昼夕食後・就寝前　7日分\n（8〜14日目）トラマドール塩酸塩口腔内崩壊錠25 mg\n1回2錠（1日8錠）\n1日4回　朝昼夕食後・就寝前　7日分\n（15日目〜）トラマドール塩酸塩口腔内崩壊錠25 mg\n1回3錠（1日12錠）\n1日4回　朝昼夕食後・就寝前　14日分\n\n検査値：血清クレアチニン0.9 mg/dL、BUN 31 mg/dL、AST 38 U/L、ALT 45 U/L、総ビリルビン1.2 mg/dL",
    field: "薬理",

    question:
      "副作用発現の作用機序として、最も適切なのはどれか。1つ選べ。",

