    field: "薬剤",

    question:
      "初日はボリコナゾールとして1回300 mgを1日2回、2日目以降は1回200 mgを1日2回点滴静注し、治療を行ったが、症状やレントゲン陰影の改善はみられなかった。この患者におけるボリコナゾールの定常状態での平均血漿中濃度は1.0 mg/Lであったため、薬剤師は治療域に達していないと判断した。\nこの患者における定常状態における平均血漿中濃度を2.5 mg/Lとしたい。ボリコナゾールの1日投与量（mg/day）として最も適切なのはどれか。1つ選べ。\nただし、ボリコナゾールの定常状態における平均血漿中濃度と体内からの消失速度の関係はMichaelis-Menten式で表され、K_m値は0.50 mg/Lとする。",

    choices: [
    "500",
    "600",
    "700",
    "800",
    "1,000"
    ],

    answer: 0,


    explanation:
      "ボリコナゾールは非線形消失を示すため、投与速度＝Vmax・C/（Km＋C）で考えます。現在は1日400 mgで平均血漿中濃度が1.0 mg/Lなので、400＝Vmax×1.0/（0.50＋1.0）より、Vmax＝600 mg/dayとなります。目標濃度2.5 mg/Lでは、投与速度＝600×2.5/（0.50＋2.5）＝500 mg/dayとなるため、正答は1です。2の600 mg/dayはVmaxに相当し、理論上は濃度が大きく上昇しやすく、目標2.5 mg/Lには合いません。3〜5は消失能を超える投与量となるため不適切です。"
