      "28歳女性。日頃から月経による出血量が多く、痛みも強い。食事は炭水化物中心で不規則だった。3ヶ月前から階段を上がるときに息切れを感じていたが、運動不足と寝不足が原因と考え、放置していた。2週間前より動悸、息切れ、めまいなどの自覚症状が増強した。かかりつけ医を受診したところ、顔面や眼瞼結膜の蒼白などの他覚症状が認められ、血液検査でヘモグロビン値7.2 g/dL、赤血球数260万/μLであった。下記の薬剤が処方され来局した。\n\n（処方）\nクエン酸第一鉄ナトリウム錠50 mg　1回2錠（1日2錠）\n1日1回　夕食後　14日分\n\n薬局の薬剤師は患者から、膝の外傷部の化膿に対して整形外科からセフジトレンピボキシル錠と耐性乳酸菌製剤が処方され、数日前から服用中であることを聴取した。",
