      "40歳男性。自営業。アトピー性皮膚炎の治療のため、かかりつけの薬局を利用している。この度、市から通知された特定健康診査を受け、下記の検査結果を持って来局した。身長176 cm、体重79 kg、腹囲86 cm、収縮期血圧138 mmHg、拡張期血圧88 mmHg、尿蛋白（－）、尿糖（－）、中性脂肪124 mg/dL、HDL-C 48 mg/dL、空腹時血糖値93 mg/dL、HbA1c 5.5％（NGSP値）。心電図異常なし。喫煙歴21歳頃から1日20本程度。この検査結果を踏まえて、医師から禁煙を強く勧められたとのことであった。",
