    caseContext:
      "71歳男性。膵臓がんで入院治療していたが、本人の希望もあり退院し、自宅で緩和ケアを受けている。退院時は以下の処方であった。薬剤師が訪問したところ、痛みの評価はNRS（数値スケール）で5、強い痛みがある場合は、モルヒネのレスキュー薬を使用していた。また、最近、「薬が飲みにくい」という訴えもある。本人は、毎日お風呂に入りたいという希望がある。\n（処方）\nモルヒネ塩酸塩水和物徐放性カプセル120 mg　1回1カプセル（1日1カプセル）　1日1回　夕食後　14日分\nモルヒネ塩酸塩水和物内用液10 mg　1回2包（10 mg/包）　痛いとき　20回分（全40包）\n酸化マグネシウム　1回0.5 g（1日0.5 g）　1日1回　就寝前　14日分",
