      "4歳男児。体重17 kg。脳性麻痺で以下の薬剤が処方された。\n\n（処方）\nダントロレンナトリウム水和物カプセル 25 mg\n1回0.3カプセル（1日0.6カプセル）\n1日2回 朝夕食後 14日分\n\n1包あたり0.3 gになるように賦形剤を加えて調剤する場合、この処方を全量調剤するために加える賦形剤の総量（g）として正しいのはどれか。1つ選べ。なお、ダントロレンナトリウム水和物カプセル1カプセルあたりの内容量は0.25 gである。",

